    /** Source from which the lead was obtained. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getLeadSources
     */
    leadSource?: string | Expression<string>;
    /** Mailing City
     */
    mailingCity?: string | Expression<string>;
    /** Mailing Country
     */
    mailingCountry?: string | Expression<string>;
    /** Mailing State
     */
    mailingState?: string | Expression<string>;
    /** Street address for mailing address
     */
    mailingStreet?: string | Expression<string>;
    /** Mailing Postal Code
     */
    mailingPostalCode?: string | Expression<string>;
    /** Contact’s mobile phone number
     */
    mobilePhone?: string | Expression<string>;
    /** Other City
     */
    otherCity?: string | Expression<string>;
    /** Other Country
     */
    otherCountry?: string | Expression<string>;
    /** Telephone for alternate address
     */
    otherPhone?: string | Expression<string>;
    /** Other Postal Code
     */
    otherPostalCode?: string | Expression<string>;
    /** Other State
     */
    otherState?: string | Expression<string>;
    /** Street for alternate address
     */
    otherStreet?: string | Expression<string>;
    /** The user who owns the contact
     * @searchListMethod searchUsers
     * @default {"mode":"list","value":""}
     */
    owner?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
    /** Phone number for the contact
     */
    phone?: string | Expression<string>;
    /** Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
     * @loadOptionsMethod getRecordTypes
     */
    recordTypeId?: string | Expression<string>;
    /** Honorific abbreviation, word, or phrase to be used in front of name in greetings, such as Dr. or Mrs.
     */
    salutation?: string | Expression<string>;
    /** The contact's personal pronouns
     */
    pronouns?: string | Expression<string>;
    /** The contact's gender identity
     */
    genderIdentity?: string | Expression<string>;
    /** Title of the contact such as CEO or Vice President
     */
    title?: string | Expression<string>;
